expansions.content:
// Compute reads the gomutants report under root and intersects it with the lines
// each changed file adds. Returns nil when no report is found, or when the report
// says nothing about any line this change touched: both are "nobody measured
// this change", which must not render as "the change is fully asserted".
func Compute(root string, changed []Changed) *Result {
	name := Locate(root)
	if name == "" {
		return nil
	}
	data, err := os.ReadFile(filepath.Join(root, name))
	if err != nil {
		return nil
	}
	var r raw
	if err := json.Unmarshal(data, &r); err != nil {
		return nil
	}

	res := &Result{Report: name}
	for _, c := range changed {
		muts := mutationsFor(r, c.Path)
		if muts == nil {
			continue
		}
		added := make(map[int]bool, len(c.Added))
		for _, l := range c.Added {
			added[l] = true
		}
		var survivors []Mutant
		for _, m := range muts {
			if !added[m.Line] {
				continue
			}
			switch normalize(m.Status) {
			case "killed":
				res.Killed++
			case "lived":
				res.Lived++
				survivors = append(survivors, Mutant{
					Line: m.Line, Mutator: m.Type, Original: m.Original, Replacement: m.Replacement,
				})
			}
			// not-covered, not-viable and timed-out are left out. Coverage already
			// reports lines no test runs, and the other two are mutants gomutants
			// could not decide on, not a statement about the tests.
		}
		if len(survivors) > 0 {
			res.Survived = append(res.Survived, FileSurvivors{Path: c.Path, Mutants: survivors})
		}
	}
	if res.Killed == 0 && res.Lived == 0 {
		return nil
	}
	return res
}

// Mutation is scoped to the lines the change adds. A survivor off the diff (line
// 40) is another change's problem; a not-covered mutant (line 50) is coverage's
// story, not this one.
func TestComputeScopesToAddedLines(t *testing.T) {
	dir := writeReport(t, "mutants.json", sample)
	res := mutation.Compute(dir, []mutation.Changed{{Path: "internal/foo/foo.go", Added: []int{10, 12}}})
	if res == nil {
		t.Fatal("a report with mutants on changed lines must produce a result")
	}
	if res.Killed != 1 || res.Lived != 1 {
		t.Fatalf("killed=%d lived=%d, want 1 and 1", res.Killed, res.Lived)
	}
	if len(res.Survived) != 1 || len(res.Survived[0].Mutants) != 1 {
		t.Fatalf("survivors = %+v", res.Survived)
	}
	m := res.Survived[0].Mutants[0]
	if m.Line != 12 || m.Mutator != "EXPRESSION_REMOVE" || m.Original != "!ok" || m.Replacement != "true" {
		t.Fatalf("survivor = %+v", m)
	}
}

// A gomutants report folds into the report: a Mutation section, a clickable
// survivor that opens the drawer at the line, the mutator and its uncaught
// change, and the survived line tagged on the file store for the drawer marker.
func TestReportRendersMutationSurvivors(t *testing.T) {
	html, err := HTML(HTMLInput{
		Report: &findings.Report{
			Coverage: findings.Coverage{ChangedFiles: 1, ExaminedFiles: 1},
			Mutation: &mutation.Result{
				Report: "mutants.json", Killed: 2, Lived: 1,
				Survived: []mutation.FileSurvivors{{Path: "a.go", Mutants: []mutation.Mutant{
					{Line: 7, Mutator: "CONDITIONALS_BOUNDARY", Original: "x > 0", Replacement: "x >= 0"},
				}}},
			},
		},
		Change: &change.Set{Files: []change.File{{Path: "a.go", Language: "go", Diff: "@@ -1 +1,7 @@\n+x\n"}}},
	})
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		`data-nav="mutation"`, `id="mutation"`, `class="mut-jump"`, `data-jump="a.go"`,
		`data-line="7"`, "CONDITIONALS_BOUNDARY", `data-survived="7"`,
	} {
		if !strings.Contains(html, want) {
			t.Errorf("mutation report is missing %q", want)
		}
	}
}

// Locate finds a gomutants report under root, or returns "". Absence is a normal
// answer: most repositories have no mutation report, and that is not a failure.
func Locate(root string) string {
	for _, n := range reportNames {
		if fi, err := os.Stat(filepath.Join(root, n)); err == nil && !fi.IsDir() {
			return n
		}
	}
	return ""
}

// Mutant is one surviving mutation on a line the change added: a test runs the
// line, but nothing fails when the line is changed this way. Original and
// Replacement name the change that went uncaught, which is the assertion a test
// is missing.
type Mutant struct {
	Line        int    `json:"line"`
	Mutator     string `json:"mutator"`
	Original    string `json:"original,omitempty"`
	Replacement string `json:"replacement,omitempty"`
}

// Result is the diff-scoped mutation picture: of the mutants that sit on the
// lines this change adds, how many a test killed, how many lived, and the
// survivors themselves. Killed and Lived count only lines this change touched,
// so the number describes the change and not the whole repository.
type Result struct {
	Report   string          `json:"report"`
	Killed   int             `json:"killed"`
	Lived    int             `json:"lived"`
	Survived []FileSurvivors `json:"survived,omitempty"`
}

// gomutants pointed at a package writes a shorter file_name than the
// repository-relative path redline holds; a suffix match must still find it.
func TestComputeMatchesBySuffix(t *testing.T) {
	dir := writeReport(t, "mutants.json", `{"files":[{"file_name":"foo.go","mutations":[
	  {"type":"X","status":"LIVED","line":3,"original":"a","replacement":"b"}]}]}`)
	res := mutation.Compute(dir, []mutation.Changed{{Path: "internal/foo/foo.go", Added: []int{3}}})
	if res == nil || res.Lived != 1 {
		t.Fatalf("suffix match failed: %+v", res)
	}
}

// A report that says nothing about any line the change touched is "nobody
// measured this change", which must read as nil, not as a clean result.
func TestComputeNilWhenNothingOnChangedLines(t *testing.T) {
	dir := writeReport(t, "mutants.json", sample)
	if res := mutation.Compute(dir, []mutation.Changed{{Path: "internal/foo/foo.go", Added: []int{99}}}); res != nil {
		t.Fatalf("no measured line must read as nil, got %+v", res)
	}
}

// Report is the merged result of one Redline run.
type Report struct {
	SchemaVersion int               `json:"schemaVersion"`
	BaseRef       string            `json:"baseRef"`
	BaseSHA       string            `json:"baseSHA,omitempty"`
	Scope         []string          `json:"scope,omitempty"`
	Findings      []Finding         `json:"findings"`
	Substrates    []SubstrateStatus `json:"substrates"`
	NewCount      map[Severity]int  `json:"newCount"`
	Coverage      Coverage          `json:"coverage"`

	Confirmations []Confirmation `json:"confirmations,omitempty"`
	Unknowns      []Unknown      `json:"unknowns,omitempty"`

	// Agent is the review narrative the agent wrote, read from review.json: an
	// overview of the change and a per-file summary, rendered as the agent's.
	Agent *AgentReview `json:"agent,omitempty"`

	// Mutation is the diff-scoped result of a gomutants report, when one is on
	// disk: of the mutants on the lines this change adds, which a test killed and
	// which lived. A lived mutant is a line a test runs but nothing asserts. Nil
	// when no report was found.
	Mutation *mutation.Result `json:"mutation,omitempty"`
}

// FileSurvivors is one file's surviving mutants on the lines a change added.
type FileSurvivors struct {
	Path    string   `json:"path"`
	Mutants []Mutant `json:"mutants"`
}

// Changed is one changed file and the new-side line numbers it added.
type Changed struct {
	Path  string
	Added []int
}

func TestComputeNilWhenNoReport(t *testing.T) {
	if res := mutation.Compute(t.TempDir(), []mutation.Changed{{Path: "a.go", Added: []int{1}}}); res != nil {
		t.Fatalf("no report must read as nil, got %+v", res)
	}
}

// Run executes every applicable pane. Applicability is computed from the diff,
// never chosen by a caller: if the caller decides which checks to run, coverage
// becomes a sample from a distribution and a check can be silently skipped.
func Run(opts Options) (*Result, error) {
	tgt, err := target.Resolve(target.Options{
		Dir: opts.Dir, PR: opts.PR, Branch: opts.Branch,
		Commit: opts.Commit, Range: opts.Range, Base: opts.Base,
	})
	if err != nil {
		return nil, err
	}
	// Panes observe the target's directory. For a PR or a branch that is a
	// detached worktree at the head commit, so "the working tree" and "the
	// revision under review" are the same thing and no pane needs to know
	// which kind of target it is looking at.
	repo, err := gitx.Open(tgt.Dir)
	if err != nil {
		return nil, err
	}
	if tgt.Base != "" {
		opts.Base = tgt.Base
	}
	baseRef := resolveRef(repo, opts.Base)
	if baseRef == "" {
		return nil, fmt.Errorf("cannot determine a base revision: tried %s. "+
			"Pass --base REF, or make a first commit if this repository has none",
			strings.Join(defaultRefs, ", "))
	}
	baseSHA, err := repo.MergeBase(baseRef)
	if err != nil {
		return nil, fmt.Errorf("base %q: %w", baseRef, err)
	}
	changed, err := repo.ChangedPaths(baseSHA)
	if err != nil {
		return nil, err
	}
	changed = excludeOwnOutput(changed, opts.Out, repo.Root)

	// Generated output leaves the change here, before any pane or the report
	// sees it, so the coverage denominator counts files a reviewer would
	// actually read. What was dropped is recorded and shown: an exclusion the
	// reader cannot see is indistinguishable from a file that never changed.
	changed, generated := change.Generated(tgt.Dir, changed, repo.AttrSet("linguist-generated", changed))

	res := &Result{Evidence: map[string]pane.Artifact{}, Target: tgt, Report: findings.Report{
		BaseRef: baseRef,
		BaseSHA: baseSHA,
		Scope:   changed,
	}}

	panes := []pane.Pane{
		&migrations.Pane{Repo: repo, UpstreamRef: resolveRef(repo, opts.Upstream, baseRef), Dir: opts.MigDir},
		&openapi.Pane{Repo: repo},
		&lint.Delta{Repo: repo},
		&lint.Suppressions{Repo: repo},
		&lint.Config{Repo: repo},
	}

	// Every path in the tree under review, listed once and only if a pane
	// turns out to have nothing in the change to look at. It answers a
	// different question from scope: not "does this pane apply to the change"
	// but "does this pane apply to the repository". A repository with no
	// migrations gets no mention of migrations; one whose migrations this
	// change did not touch is told so, quietly.
	var allPaths []string
	listAll := func() []string {
		if allPaths != nil {
			return allPaths
		}
		var blobs map[string]string
		var lerr error
		if tgt.Head == "" {
			blobs, lerr = repo.WorktreeBlobs()
		} else {
			blobs, lerr = repo.Blobs(tgt.Head)
		}
		if lerr != nil {
			// Unknown whether the pane applies: fall back to saying it was
			// skipped, the state that still gets a line on the report.
			allPaths = []string{}
			return allPaths
		}
		allPaths = make([]string, 0, len(blobs))
		for path := range blobs {
			allPaths = append(allPaths, path)
		}
		sort.Strings(allPaths)
		return allPaths
	}

	examined := map[string]bool{}
	for _, p := range panes {
		status := findings.SubstrateStatus{Name: p.Name()}
		scope := p.Scope(changed)
		for _, path := range scope {
			examined[path] = true
		}
		if len(scope) == 0 {
			// Scope over the whole tree is only consulted for a pane that will
			// not run, so the state it leaves behind in the pane is unused.
			if all := listAll(); len(all) > 0 && len(p.Scope(all)) == 0 {
				status.State = findings.SubstrateNotApplicable
				status.Detail = "the repository has no files this pane reads"
			} else {
				status.State = findings.SubstrateSkipped
				status.Detail = "this change touches none of the files this pane reads"
			}
			res.Report.Substrates = append(res.Report.Substrates, status)
			continue
		}
		out, err := runPane(p, baseSHA)
		if err != nil {
			// A pane that applied but did not run is recorded as failed and
			// as an unknown; it never reads as a pass.
			status.State = findings.SubstrateFailed
			status.Detail = err.Error()
			res.Report.Substrates = append(res.Report.Substrates, status)
			res.Report.Unknowns = append(res.Report.Unknowns, findings.Unknown{
				Substrate: p.Name(),
				Message:   "pane applied to this change but did not run",
				Reason:    err.Error(),
			})
			continue
		}
		status.State = findings.SubstrateRan
		res.Report.Substrates = append(res.Report.Substrates, status)
		res.Report.Findings = append(res.Report.Findings, out.Findings...)
		res.Report.Confirmations = append(res.Report.Confirmations, out.Confirmations...)
		res.Report.Unknowns = append(res.Report.Unknowns, out.Unknowns...)
		res.Renders = append(res.Renders, out.Render)
		for id, a := range out.Evidence {
			res.Evidence[id] = a
		}
	}

	res.Report.Coverage = coverage(changed, examined)
	res.Report.Coverage.Generated = generated
	res.Report.Unknowns = append(res.Report.Unknowns, unbuiltPanes(changed, examined)...)
	// The agent's review, if it has written one. Loaded before Finalize so its
	// line comments become findings that get fingerprints stamped with the rest;
	// verdicts merge after, joining on those fingerprints. Never fatal: a run
	// reports facts with or without a reading, and a broken file is stated.
	review, verr := findings.LoadReview(filepath.Join(opts.Out, "review.json"))
	if verr != nil {
		res.Report.Unknowns = append(res.Report.Unknowns, findings.Unknown{
			Substrate: "redline/review",
			Message:   "review.json was present but could not be read, so no agent review was merged",
			Reason:    verr.Error(),
		})
	}
	if review != nil {
		res.Report.Findings = append(res.Report.Findings, review.CommentFindings()...)
		if review.Overview != "" || len(review.Files) > 0 {
			res.Report.Agent = &findings.AgentReview{Overview: review.Overview, Files: review.Files}
		}
	}
	if res.Report.Coverage.ExaminedFiles == 0 && len(changed) > 0 {
		// No pane looked at any of it. This is not a clean review and must
		// never render as one. Stated after the agent's comments merge, so
		// the reason can be honest about whether the findings list is empty.
		reason := "this change is entirely unexamined; the empty findings list below is not evidence of correctness"
		if len(res.Report.Findings) > 0 {
			reason = "no pane covers these files; the findings below come from the agent's review"
		}
		res.Report.Unknowns = append(res.Report.Unknowns, findings.Unknown{
			Substrate: "redline",
			Message:   fmt.Sprintf("none of the %d changed file(s) fall under any pane Redline currently ships", len(changed)),
			Reason:    reason,
		})
	}
	res.Report.Finalize()
	if review != nil {
		res.Report.MergeVerdicts(review.Verdicts)
	}
	findings.Sort(res.Report.Findings)

	res.Change = change.Build(repo, tgt, baseSHA, changed)
	covDir := originCoverageDir(opts.Dir, tgt)
	attachDiffCoverage(&res.Report, res.Change, tgt.Dir, covDir)
	res.LineCoverage = lineCoverageOverlay(tgt.Dir, covDir, res.Change)
	attachMutation(&res.Report, res.Change, opts.Dir)
	return res, nil
}

// mutationSection renders the diff-scoped gomutants result, when a report was
// read. A survivor is a line a test runs but nothing asserts.
func mutationSection(b *strings.Builder, rep *findings.Report) {
	m := rep.Mutation
	if m == nil {
		return
	}
	fmt.Fprintf(b, "## Mutation\n\n")
	fmt.Fprintf(b, "%d mutant(s) on the added lines survived (a test runs the line but nothing fails when it changes); %d killed. From `%s`.\n\n",
		m.Lived, m.Killed, m.Report)
	for _, fs := range m.Survived {
		for _, mt := range fs.Mutants {
			fmt.Fprintf(b, "- `%s:%d` — %s", fs.Path, mt.Line, mt.Mutator)
			if mt.Original != "" {
				fmt.Fprintf(b, ": `%s` -> `%s`", mt.Original, mt.Replacement)
			}
			fmt.Fprintln(b)
		}
	}
	if len(m.Survived) > 0 {
		fmt.Fprintln(b)
	}
}

// attachMutation reads a gomutants report from the directory redline was run in
// and scopes it to the change. Unlike coverage it does not fall back to the
// origin checkout: the report is written where the developer or CI ran
// gomutants, which is this working directory, not the pristine worktree the
// panes observe. Nil result when no report is present, the same silence the
// cover package keeps when there is no profile.
func attachMutation(rep *findings.Report, ch *change.Set, dir string) {
	if ch == nil || len(ch.Files) == 0 {
		return
	}
	changed := make([]mutation.Changed, 0, len(ch.Files))
	for _, f := range ch.Files {
		if filepath.Ext(f.Path) != ".go" {
			continue
		}
		changed = append(changed, mutation.Changed{Path: f.Path, Added: cover.AddedLines(f.Diff)})
	}
	if len(changed) == 0 {
		return
	}
	rep.Mutation = mutation.Compute(dir, changed)
}

// mutationsFor matches a repository path against gomutants' file_name. That name
// is relative to the common ancestor of the paths gomutants was pointed at: run
// on ./... from the module root it is repository-relative and matches exactly, a
// narrower target makes it a path suffix. Match by longest path-component suffix,
// the same tactic cover.blocksFor uses for import-qualified profile keys.
func mutationsFor(r raw, path string) []rawMutant {
	var best []rawMutant
	bestLen := -1
	for i := range r.Files {
		f := r.Files[i]
		if f.FileName == path || strings.HasSuffix(path, "/"+f.FileName) {
			if len(f.FileName) > bestLen {
				best, bestLen = f.Mutations, len(f.FileName)
			}
		}
	}
	return best
}

const sample = `{
  "go_module": "example.com/x",
  "files": [
    {"file_name": "internal/foo/foo.go", "mutations": [
      {"type":"CONDITIONALS_BOUNDARY","status":"KILLED","line":10,"replacement":">="},
      {"type":"EXPRESSION_REMOVE","status":"LIVED","line":12,"original":"!ok","replacement":"true"},
      {"type":"RETURN_ZERO","status":"LIVED","line":40,"replacement":"0"},
      {"type":"INTEGER_INCREMENT","status":"NOT COVERED","line":50}
    ]}
  ]
}`

func buildView(in HTMLInput) view {
	rep := in.Report
	v := view{
		Title:    "Redline",
		Coverage: rep.Coverage,
		Renders:  in.Renders,
		Confirms: rep.Confirmations,
		Unknowns: rep.Unknowns,
		Failed:   rep.FailedSubstrates(),
		Counts:   map[string]int{},
	}
	for _, s := range rep.Substrates {
		if s.State == findings.SubstrateSkipped {
			v.Skipped = append(v.Skipped, s)
		}
	}
	head := "worktree"
	if ch := in.Change; ch != nil {
		v.Commits = len(ch.Commits)
		v.UITouched = ch.UITouched
		if ch.Target != nil {
			v.Subtitle = ch.Target.Describe()
			if ch.Target.Head != "" {
				head = ch.Target.Head
			}
			if ch.Target.PR != nil {
				v.URL = ch.Target.PR.URL
				v.Author = ch.Target.PR.Author
			}
		}
	}
	v.Identity = reviewIdentity(rep.BaseSHA, head, in.Change)
	if v.Subtitle == "" {
		v.Subtitle = fmt.Sprintf("base %s", short(rep.BaseSHA))
	}
	v.Banner = bannerText(rep)
	if rep.Agent != nil {
		v.Overview = rep.Agent.Overview
	}
	v.Mutation = rep.Mutation

	for _, f := range rep.Findings {
		v.Counts[string(f.Severity)]++
		fv := findingView{Finding: f}
		for _, id := range f.Evidence {
			if a, ok := in.Evidence[id]; ok && a.Content != "" && len(a.Content) < maxInlineEvidence {
				fv.Evidence = template.HTML(highlightDiff(a.Content))
			}
		}
		v.Observed = append(v.Observed, fv)
	}

	if in.Change != nil {
		count, worst := fileFindingCounts(rep.Findings)
		findingLines := map[string][]int{}
		for _, f := range rep.Findings {
			if f.File != "" && f.Line > 0 {
				findingLines[f.File] = append(findingLines[f.File], f.Line)
			}
		}
		headDir := ""
		if in.Change.Target != nil {
			headDir = in.Change.Target.Dir
		}
		survived := map[string][]int{}
		if rep.Mutation != nil {
			for _, fs := range rep.Mutation.Survived {
				for _, m := range fs.Mutants {
					survived[fs.Path] = append(survived[fs.Path], m.Line)
				}
			}
		}
		seen := map[string]bool{}
		for _, g := range change.CompositionGroups(in.Change.Files) {
			dg := drillGroup{Label: g.Language + " " + g.Kind, Count: len(g.Files), Added: g.Added, Removed: g.Removed}
			for _, f := range g.Files {
				diff := expandForFindings(headDir, f.Path, f.Diff, findingLines[f.Path])
				fv := fileView{Path: f.Path, Status: f.Status, Added: f.Added, Removed: f.Removed,
					Findings: count[f.Path], Severity: string(worst[f.Path]),
					Diff: template.HTML(highlightDiffFor(f.Path, diff, in.LineCoverage[f.Path]))}
				if rep.Agent != nil {
					fv.Summary = rep.Agent.Files[f.Path]
				}
				fv.Survived = survived[f.Path]
				dg.Files = append(dg.Files, fv)
				if !seen[f.Path] {
					seen[f.Path] = true
					v.DiffFiles = append(v.DiffFiles, fv)
				}
			}
			v.Groups = append(v.Groups, dg)
		}
	}
	v.Nav = navFor(v)
	return v
}

// rawMutant mirrors one entry of a gomutants report's per-file mutations list.
type rawMutant struct {
	Type        string `json:"type"`
	Status      string `json:"status"`
	Line        int    `json:"line"`
	Original    string `json:"original"`
	Replacement string `json:"replacement"`
}

func writeReport(t *testing.T, name, body string) string {
	t.Helper()
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o644); err != nil {
